def test_AC23_8_5_balance_passes_but_field_accuracy_regresses(tmp_path: Path) -> None:
    'AC-llm.8.5'; from common.testing.check_llm_cassettes import balance_violation
    def _same_direction(a: dict, b: dict) -> bool:
        da = str(a.get('direction') or '').strip().upper(); db = str(b.get('direction') or '').strip().upper()
        if da or db: return da == db
        return (Decimal(str(a['amount'])) < 0) == (Decimal(str(b['amount'])) < 0)
    def _pick_pair(case) -> tuple[int, int] | None:
        txns = case.extracted.get('transactions') or []
        for i in range(len(txns)):
            for j in range(i + 1, len(txns)):
                if _same_direction(txns[i], txns[j]): return (i, j)
        return None
    cases = load_cases(); target, pair = next(((c, p) for c in cases if balance_violation(c.extracted) is None and (p := _pick_pair(c)) is not None)); i, j = pair; plausible = json.loads(json.dumps(target.extracted)); ti, tj = (plausible['transactions'][i], plausible['transactions'][j]); ti['amount'] = str(Decimal(str(ti['amount'])) + Decimal('1')); tj['amount'] = str(Decimal(str(tj['amount'])) - Decimal('1')); assert balance_violation(plausible) is None; correct_score, _ = case_score(target.extracted, target.truth); plausible_score, _ = case_score(plausible, target.truth); assert plausible_score < correct_score; baseline_file = tmp_path / 'baseline.jsonl'; from common.testing.cassette_eval_baseline import write_jsonl; write_jsonl(baseline_file, {'version': 1, 'cases': {target.case_id: {'score': correct_score, 'metric': 'field-accuracy', 'provenance': 'test'}}}); findings = evaluate(baseline_path=baseline_file, overrides={target.case_id: [plausible]}); assert any((target.case_id in r for r in findings['regressions'])), findings
