def test_AC23_8_6_ground_truth_artifacts_are_synthetic() -> None:
    'AC-llm.8.6'; import re; from common.testing.cassette_graded_eval import CASSETTE_DIR, _parse_extraction; from common.testing.fixtures.extraction_pii_mask import _DESC_KEYS; pseudonym = re.compile('[0-9a-f]{2}\\*+[0-9a-f]{2}|\\*+'); safe_string_keys = {'institution', 'currency', 'period_start', 'period_end', 'opening_balance', 'closing_balance', 'opening', 'closing', 'date', 'amount', 'direction', 'balance_after', 'suggested_category', 'symbol', 'ticker', 'isin', 'asset_identifier', 'asset_type', 'quantity', 'market_value', 'price'}; cjk = re.compile('[\u3040-ヿ㐀-䶿一-鿿가-\ud7af豈-\ufaff]')
    def _assert_pii_free(name: str, obj: object) -> None:
        if isinstance(obj, dict):
            for (key, value) in obj.items():
                if not isinstance(value, str): _assert_pii_free(name, value)
                elif key in safe_string_keys: continue
                elif key in _DESC_KEYS: assert pseudonym.fullmatch(value), f'{name}: description {key!r}={value!r} is not an irreversible pseudonym (hex+stars+hex) nor fully redacted'
                else: assert value == '**', f"{name}: text field {key!r}={value!r} is neither an allowlisted non-PII field nor fully redacted to '**'"
        else: [_assert_pii_free(name, item) for item in obj] if isinstance(obj, list) else None
    for path in sorted(GROUND_TRUTH_DIR.glob('*.truth.json')):
        data = json.loads(path.read_text(encoding='utf-8'))
        if data.get('synthetic') is True: continue
        assert data.get('synthetic') is False, f"{path.name}: 'synthetic' must be set true or false"; extraction = _parse_extraction(CASSETTE_DIR / f"{path.name[:-len('.truth.json')]}.json"); assert extraction is not None, f'{path.name}: no scorable cassette to verify PII-masking'; assert not cjk.search(json.dumps(extraction, ensure_ascii=False)), f'{path.name}: a CJK character (likely a real name) survives in a committed real cassette'; _assert_pii_free(path.name, extraction)
